WITH s0 AS (SELECT * FROM features),
s1 AS (SELECT *, (efficiency_24 < 0.25) AS _condition_0 FROM s0),
s2 AS (SELECT *, (range_position_24 >= 0.0) AS _condition_1 FROM s1),
s3 AS (SELECT *, (range_position_24 < 0.15) AS _condition_2 FROM s2),
s4 AS (SELECT *, (_condition_1 AND _condition_2) AS _condition_3 FROM s3),
s5 AS (SELECT *, CASE WHEN count(_condition_3) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) = 3 THEN bool_or(_condition_3) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) END AS _condition_4 FROM s4),
s6 AS (SELECT *, (range_position_24 >= 0.15) AS _condition_5 FROM s5),
s7 AS (SELECT *, (range_position_24 < 0.5) AS _condition_6 FROM s6),
s8 AS (SELECT *, (_condition_5 AND _condition_6) AS _condition_7 FROM s7),
s9 AS (SELECT *, CASE WHEN count(_condition_7) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) = 2 THEN bool_and(_condition_7) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) END AS _condition_8 FROM s8),
s10 AS (SELECT *, (range_atr < 1.5) AS _condition_9 FROM s9),
s11 AS (SELECT *, (range_width_atr_24 > 4.0) AS _condition_10 FROM s10),
s12 AS (SELECT *, (_condition_0 AND _condition_4 AND _condition_8 AND _condition_9 AND _condition_10) AS _condition_11 FROM s11),
s13 AS (SELECT *, (efficiency_24 < 0.25) AS _condition_12 FROM s12),
s14 AS (SELECT *, (range_position_24 > 0.85) AS _condition_13 FROM s13),
s15 AS (SELECT *, (range_position_24 <= 1.0) AS _condition_14 FROM s14),
s16 AS (SELECT *, (_condition_13 AND _condition_14) AS _condition_15 FROM s15),
s17 AS (SELECT *, CASE WHEN count(_condition_15) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) = 3 THEN bool_or(_condition_15) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) END AS _condition_16 FROM s16),
s18 AS (SELECT *, (range_position_24 <= 0.85) AS _condition_17 FROM s17),
s19 AS (SELECT *, (range_position_24 > 0.5) AS _condition_18 FROM s18),
s20 AS (SELECT *, (_condition_17 AND _condition_18) AS _condition_19 FROM s19),
s21 AS (SELECT *, CASE WHEN count(_condition_19) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) = 2 THEN bool_and(_condition_19) OVER (PARTITION BY instrument ORDER BY bar_open_time ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) END AS _condition_20 FROM s20),
s22 AS (SELECT *, (range_atr < 1.5) AS _condition_21 FROM s21),
s23 AS (SELECT *, (range_width_atr_24 > 4.0) AS _condition_22 FROM s22),
s24 AS (SELECT *, (_condition_12 AND _condition_16 AND _condition_20 AND _condition_21 AND _condition_22) AS _condition_23 FROM s23),
s25 AS (SELECT *, (range_position_24 >= 0.5) AS _condition_24 FROM s24),
s26 AS (SELECT *, (range_position_24 <= 0.5) AS _condition_25 FROM s25)
SELECT instrument, bar_open_time, bar_close_time, coalesce(_condition_11, FALSE) AS entry_long, coalesce(_condition_23, FALSE) AS entry_short, coalesce(_condition_24, FALSE) AS exit_long, coalesce(_condition_25, FALSE) AS exit_short FROM s26 ORDER BY instrument, bar_open_time
